import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const admin=readFileSync('app/admin/whatsapp/page.tsx','utf8');
const docs=readFileSync('docs/WHATSAPP_META_SETUP.md','utf8');
assert(admin.includes('Keep mobile WhatsApp Business and reconnect Cloud API'), 'Coexistence action plan should be visible in WhatsApp HQ');
assert(admin.includes('aria-label="Keep WhatsApp Business mobile and reconnect Cloud API"'), 'Accessible section must be discoverable');
assert(admin.includes('Connect existing WhatsApp Business app'), 'Do not promote ordinary Cloud API registration');
assert(admin.includes('do not use the ordinary'), 'Coexistence must warn against ordinary Add phone flow');
assert(admin.includes('eligible Solution Partner or Tech Provider'), 'Do not claim Zeshu is a Meta Tech Provider');
assert(admin.includes('Signed Meta callbacks observed (historical total)'), 'Historical telemetry must not prove current Cloud registration');
assert(admin.includes('Inbound messages recorded (historical total)'), 'Historical inbox messages must not prove reconnection');
assert(!admin.includes('The inbox currently has no customer messages.'), 'Remove disproven zero-inbox claim');
assert(!admin.includes('Use the official WhatsApp Cloud API with Zeshu\'s existing Meta business account instead'), 'Old API-only guidance is misleading after mobile registration');
assert(admin.includes('customer sending remains OFF'), 'Outbound WhatsApp must stay disabled');
assert(admin.includes('Meta: WhatsApp Business app Coexistence guide'), 'Direct link to Meta official signup guide should be present');
assert(docs.includes('22 November 2026 — owner has moved number back'), 'Document user-reported new state');
assert(docs.includes('Standard \`POST /{phone-number-id}/register\`'), 'Deny direct API register shortcut');
assert(docs.includes('Historical database webhook counters'), 'Explain historical counts');
assert(docs.includes('Do not assume a partner-issued API key works as an existing system-user token'), 'Provider token migration must be explicit');
console.log('PASS: WhatsApp Business mobile Coexistence safety guidance and historical telemetry disclosure.');
